<?php
namespace ZinCelestial\Platform\Admin;use ZinCelestial\Platform\Assets\Rollback\SnapshotManager;defined('ABSPATH')||exit;
final class AssetController{public function register():void{add_action('admin_post_zcp_asset_snapshot',array($this,'snapshot'));add_action('admin_post_zcp_asset_rollback',array($this,'rollback'));}public function snapshot():void{$this->guard('zcp_asset_snapshot');(new SnapshotManager())->create((array)get_option('zcp_asset_rules',array()),'manual');$this->back('snapshot');}public function rollback():void{$this->guard('zcp_asset_rollback');(new SnapshotManager())->restore(sanitize_text_field(wp_unslash($_POST['snapshot_id']??'')));$this->back('rollback');}private function guard(string $action):void{if(!current_user_can('manage_options'))wp_die(esc_html__('Insufficient permissions.','zincelestial-platform'));check_admin_referer($action);}private function back(string $done):void{wp_safe_redirect(admin_url('admin.php?page=zcp-assets&done='.$done));exit;}}
